// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Glyphs".

FX animation. Sorry, had no time to comment the shader's code.
*/

const scale = Math.max(1, devicePixelRatio/2)
let theShader, moves=[0,0];

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2931596/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	mouseMove()
	shader(theShader)
	theShader.setUniform("resolution", [width * scale, height * scale])
	theShader.setUniform("time", millis() / 1000.0)
	theShader.setUniform("move", moves)
	rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// Provides a condensed timeline, such as the accelerated movement of a second hand between the values.
float tick(float a, float b) {
	return floor(a)+pow(fract(a),b);
}
// Returns the SDF of a box
float box(vec3 p, vec3 s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z));
}
// Returns the SDF of a line segment for a 3d point
float line(vec3 p, vec3 a, vec3 b, float r) {
  p=p-a, b=b-a;
  float h=clamp(dot(p,b)/dot(b,b),.0,1.);
  return length(p-b*h)-r;
}
// Returns the SDF if a line segment for a 2d point
float line(vec2 p, vec2 a, vec2 b, float r) {
  p=p-a, b=b-a;
  float h=clamp(dot(p,b)/dot(b,b),.0,1.);
  return length(p-b*h)-r;
}

float pattern(vec2 p) {
	float x=SE(max(abs(p.x),abs(p.y)),.2);
	x=max(x,SE(line(p,vec2(1,-1),vec2(-1,1),.0),.1));
	x=max(x,SE(line(p,vec2(-1,-1),vec2(1,1),.0),.1));

	float f=SE(line(p, vec2(-1,1), vec2(.5,1),.0),.1);
	f=max(f,SE(line(p, vec2(-1,.125), vec2(0,.125),.0),.1));
	f=max(f,SE(line(p, vec2(-1), vec2(-1,1),.0),.1));

	return mix(f,x,sin(-1.5707+3.14159*tick(T,14.))*.5+.5);
}

float shapeX(vec2 p) {
	return min(
		line(p,vec2(1,-1),vec2(-1,1),.2),
		line(p,vec2(-1),vec2(1),.2)
	);
}

float F(vec2 p, float s) {
	return min(
		min(
			line(p, vec2(-1,1), vec2(.5,1), s),
			line(p, vec2(-1,.125), vec2(0,.125), s)
		),
		line(p, vec2(-1), vec2(-1,1), s)
	);
}

float X(vec2 p) {
	 p=abs(p);
	 return length(p-min(p.x+p.y,2.)*.5)-.2;
}

float shapeX(vec3 p, float h) {
	float d=X(p.xy);
	vec2 c=vec2(d,abs(p.z)-h);
	return length(max(c,.0))+min(.0,max(c.x,c.y));
}

float shapeF(vec3 p, float h) {
	float d=F(p.xy, .2);
	vec2 c=vec2(d,abs(p.z)-h);
	return length(max(c,.0))+min(.0,max(c.x,c.y));
}

vec2 map(vec3 p) {
	float d=box(p,vec3(1)), e=-(length(abs(p.xy)-.5)-.2);
	vec2
	a=vec2(d,.0),
	b=vec2(e,1.);

	a=a.x>b.x?a:b;

	b=vec2(mix(shapeF(p,1.),shapeX(p,1.),sin(-1.5707+3.14159*tick(T,14.))*.5+.5),.0);
	return b;
}

vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h).x+
		k.yxy*map(p+k.yxy*h).x+
		k.yyx*map(p+k.yyx*h).x+
		k.xxx*map(p+k.xxx*h).x
	);
}

float shadow(vec3 p, vec3 rd) {
	float shd=1., maxd=length(rd-p);
	vec3 l=N(rd-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i).x;
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd, 24.*d/i);
		i+=d;
	}
	return shd;
}

float calcAO(vec3 p, vec3 n) {
	float occ=.0, sca=1.;
	for(float i=.0; i++<5.;) {
		float
		h=.01+.12*i/4.,
		d=map(p+n*h).x;
		occ+=(h-d)*sca;
		sca*=.5;
		if(occ>.35) break;
	}
	return clamp(1.-3.*occ,.0,1.)*(.5+.5*n.y);
}

void cam(inout vec3 p) {
	p.yz*=rot(-move.y*6.3/MN);
	p.xz*=rot(-move.x*6.3/MN+tick(T,14.)*3.14159);
}

vec3 rnd(vec3 p) {
	uvec3 q=floatBitsToUint(p)*1234567891u+12345678u;
	q.x+=q.y*q.z;
	q.y+=q.x*q.z;
	q.z+=q.y*q.x;
	q^=q>>16u;
	q.x+=q.y*q.z;
	q.y+=q.x*q.z;
	q.z+=q.y*q.x;
	return vec3(q)/float(-1u);
}

float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p*34.56);
	return fract(p.x*p.y);
}

float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p*=dot(p,p+34.56);
	return fract(p.x*p.y);
}

vec2 rnd12(float a) {
	vec3 p=fract(a*vec3(243.76,297.56,301.62));
	p+=dot(p,p+34.56);
	return fract(vec2(p.x*p.y,p.y*p.z));
}
vec3 bg(vec2 uv) {
	float d=.5, e=.0, steps=40.;
	for (float i=.0; i++<steps;) {
		vec2 n=rnd12(i), p=sin(n*(7.+T*1.5)+T*.2);
		float f=dot(uv-p,uv-p);
		if (d>f) {
			d=f;
			e=i;
		}
	}
	return vec3(d);
}

float curve(float a, float b) {
	a/=b;
	return mix(
		rnd(floor(a)),
		rnd(floor(a)+1.),
		pow(S(.0,1.,fract(b)),10.)
	);
}

void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-7),
	rd=N(vec3(uv,2)),
	lp=vec3(-1,2,-3);
	cam(p); cam(rd); cam(lp);

	vec3 voxpos=vec3(rnd(FC.x),rnd(FC.y),rnd(dot(FC,FC)));
	const float
	gridsize=2.,
	gridrange=.5;

	voxpos*=gridsize;
	voxpos=floor(voxpos-.5)/gridsize;
	voxpos*=gridrange;

	rd=N(rd-voxpos*.1*pow(smoothstep(.0,1.,sin(6.28318*tick(T,7.))),16.));

	for (float i=.0; i++<400.;) {
		vec2 d=map(p);
		if (abs(d.x)<1e-3) {
			vec3 n=norm(p), l=N(lp-p);
			float shd=shadow(p+n*3e-3,lp), diff=clamp(dot(l,n),.0,1.), ao=calcAO(p,n);

			col+=.2+diff*shd*ao;

			if (d.y == .0 && abs(n.z) > .9) {
				col-=pattern(p.xy)*abs(n.z)*S(-1.,1.,sin(6.28318*T));
			}
			col+=pow(clamp(dot(reflect(rd,n),l),.0,1.),64.);
			col/=1.+exp(-col);
			col=sqrt(col);

			break;
		}
		if (d.x>20.) {
			col=bg(uv);
			break;
		}
		p+=rd*d.x;
	}

	O=vec4(col,1);
}

